95	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
96	{
97	    for (guint i = 0; i < regs->len; i++) {
98	        qemu_plugin_reg_descriptor *rd =
99	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
100	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
101	            return rd->handle;
102	        }
103	    }
104	    return NULL;
105	}
