107	// Lazily resolves register handles. The plugin's vcpu_init runs before
108	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
109	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
110	// regs at that moment. By the time the entry trigger fires, all dynamic
111	// features are registered and a fresh call returns the full list.
112	static void resolve_handles(VcpuRegs *v)
113	{
114	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
115	    for (int i = 0; i < 32; i++) {
116	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
117	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
118	    }
119	    v->pc = find_reg(regs, "pc");
120	
121	    v->mstatus  = find_reg(regs, "mstatus");
122	    v->mepc     = find_reg(regs, "mepc");
123	    v->mtvec    = find_reg(regs, "mtvec");
124	    v->mcause   = find_reg(regs, "mcause");
125	    v->mtval    = find_reg(regs, "mtval");
126	    v->mscratch = find_reg(regs, "mscratch");
127	    v->medeleg  = find_reg(regs, "medeleg");
128	    v->mideleg  = find_reg(regs, "mideleg");
129	    v->mip      = find_reg(regs, "mip");
130	    v->mie      = find_reg(regs, "mie");
131	    v->mcycle   = find_reg(regs, "mcycle");
132	    v->minstret = find_reg(regs, "minstret");
133	    v->satp     = find_reg(regs, "satp");
134	
135	    char buf[16];
136	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
137	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
138	        v->pmpcfg[i] = find_reg(regs, buf);
139	    }
140	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
141	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
142	        v->pmpaddr[i] = find_reg(regs, buf);
143	    }
144	
145	    v->vstart = find_reg(regs, "vstart");
146	    v->vxsat  = find_reg(regs, "vxsat");
147	    v->vxrm   = find_reg(regs, "vxrm");
148	    v->vcsr   = find_reg(regs, "vcsr");
149	    v->vtype  = find_reg(regs, "vtype");
150	    v->vl     = find_reg(regs, "vl");
151	    v->vlenb  = find_reg(regs, "vlenb");
152	    for (int i = 0; i < 32; i++) {
153	        g_snprintf(buf, sizeof(buf), "v%d", i);
154	        v->vreg[i] = find_reg(regs, buf);
155	    }
