158	static uint64_t read_reg64(struct qemu_plugin_register *h)
159	{
160	    if (!h) return 0;
161	    g_autoptr(GByteArray) buf = g_byte_array_new();
162	    int sz = qemu_plugin_read_register(h, buf);
163	    if (sz <= 0) return 0;
164	    uint64_t v = 0;
165	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
166	    return v;
167	}
