169	// Reads up to `dst_max` bytes from a register handle. Returns the byte
170	// count written (0 on failure or NULL handle). Used for vector regs whose
171	// width = vlenb bytes.
172	static size_t read_reg_bytes(struct qemu_plugin_register *h,
173	                             uint8_t *dst, size_t dst_max)
174	{
175	    if (!h || dst_max == 0) return 0;
176	    g_autoptr(GByteArray) buf = g_byte_array_new();
177	    int sz = qemu_plugin_read_register(h, buf);
178	    if (sz <= 0) return 0;
179	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
180	    memcpy(dst, buf->data, n);
181	    return n;
182	}
