184	// Atomic on POSIX: write to .tmp, fsync, rename.
185	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
186	{
187	    char tmp[PATH_MAX];
188	    g_snprintf(tmp, sizeof(tmp), "%s.tmp.%d", path, (int) getpid());
189	    int fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC, 0600);
190	    if (fd < 0) {
191	        perror("hybrid_handoff: open tmp");
192	        return -1;
193	    }
194	    ssize_t want = (ssize_t) sizeof(*s);
195	    ssize_t got = write(fd, s, sizeof(*s));
196	    if (got != want) {
197	        perror("hybrid_handoff: write");
198	        close(fd);
199	        unlink(tmp);
200	        return -1;
201	    }
202	    fsync(fd);
203	    close(fd);
204	    if (rename(tmp, path) != 0) {
205	        perror("hybrid_handoff: rename");
206	        unlink(tmp);
207	        return -1;
208	    }
209	    return 0;
210	}
