212	// Drain CPU state to outfile_path. pc is computed by the caller (from a
213	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
214	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
215	// minstret in the state file (used by drain_at_exit mode to record a
216	// plugin-counted retired-insn total). Does NOT call exit -- caller
217	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
218	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
219	                                uint64_t minstret_override)
220	{
221	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
222	    resolve_handles(v);
223	    struct hybrid_state_v1 s = {0};
224	    s.magic   = HYBRID_STATE_MAGIC;
225	    s.version = HYBRID_STATE_VERSION;
226	    s.flags   = HYBRID_FLAG_RV64;
227	    s.hart_id = vcpu_idx;
228	    s.priv    = 3;
229	    s.pc      = pc;
230	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
231	
232	    // Floating-point: only set FP flag if at least one handle was bound,
233	    // i.e. QEMU advertised the FPU feature (D extension).
234	    int has_fp = 0;
235	    for (int i = 0; i < 32; i++) {
236	        s.fpr[i] = read_reg64(v->fpr[i]);
237	        if (v->fpr[i]) has_fp = 1;
238	    }
239	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
240	
241	    s.mstatus  = read_reg64(v->mstatus);
242	    s.mepc     = read_reg64(v->mepc);
243	    s.mtvec    = read_reg64(v->mtvec);
244	    s.mcause   = read_reg64(v->mcause);
245	    s.mtval    = read_reg64(v->mtval);
246	    s.mscratch = read_reg64(v->mscratch);
247	    s.medeleg  = read_reg64(v->medeleg);
248	    s.mideleg  = read_reg64(v->mideleg);
249	    s.mip      = read_reg64(v->mip);
250	    s.mie      = read_reg64(v->mie);
251	    s.mcycle   = read_reg64(v->mcycle);
252	    s.minstret = minstret_override ? minstret_override
253	                                   : read_reg64(v->minstret);
254	    s.satp     = read_reg64(v->satp);
255	
256	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
257	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
258	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
259	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
260	
261	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
262	    // bounds the per-register byte count copied into vreg[].
263	    s.vstart = read_reg64(v->vstart);
264	    s.vxsat  = read_reg64(v->vxsat);
265	    s.vxrm   = read_reg64(v->vxrm);
266	    s.vcsr   = read_reg64(v->vcsr);
267	    s.vtype  = read_reg64(v->vtype);
268	    s.vl     = read_reg64(v->vl);
269	    s.vlenb  = read_reg64(v->vlenb);
270	    if (v->vlenb && s.vlenb > 0) {
271	        s.flags |= HYBRID_FLAG_V;
272	        size_t bytes = s.vlenb < HYBRID_VLEN_BYTES_MAX
273	                     ? (size_t) s.vlenb
274	                     : (size_t) HYBRID_VLEN_BYTES_MAX;
275	        for (int i = 0; i < 32; i++)
276	            (void) read_reg_bytes(v->vreg[i],
277	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
278	                                  bytes);
279	    }
280	
281	    if (write_state_atomic(&s, outfile_path) != 0) {
282	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
283	        exit(2);
284	    }
285	    fprintf(stderr,
286	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
287	            outfile_path, s.pc);
288	}
