290	static void on_handoff(unsigned int vcpu_idx, void *udata)
291	{
292	    const HandoffSite *site = (const HandoffSite *) udata;
293	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
294	    // F14: suppress the atexit drain path now that we have a real trigger.
295	    drained_already = 1;
296	    // PC via translation-time vaddr+size; reading the gdbstub PC inside the
297	    // exec callback can lag the actual current insn when V instructions
298	    // retire just before the trigger (TCG defers PC writes for performance).
299	    drain_state_to_file(vcpu_idx, compute_handoff_pc(site), 0);
300	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
301	    // Distinguishes drain from workload completion (0) so the orchestrator
302	    // can decide the next spawn.
303	    exit(200);
304	}
305	
306	// F14: per-insn tick. Increments a global counter every retired insn so the
307	// drain-at-exit path can report a true retired-insn total (independent of
308	// QEMU's PMU semantics).
309	static void on_count_tick(unsigned int vcpu_idx, void *udata)
310	{
311	    (void) vcpu_idx;
312	    (void) udata;
313	    atexit_insn_count++;
314	}
315	
316	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
317	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
318	// still set and qemu_plugin_read_register works. If any other trigger
319	// already drained, return immediately (drained_already guards against
320	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
321	// use _exit() to skip the rest of the atexit chain.
322	static void on_atexit(qemu_plugin_id_t id, void *udata)
323	{
324	    (void) id;
325	    (void) udata;
326	    if (drained_already) return;
327	    if (!drain_at_exit_mode) return;
328	    // pc=0 is a positive marker that the atexit path drained (no trigger).
329	    drain_state_to_file(0, 0, atexit_insn_count);
330	    fflush(stderr);
331	    _exit(200);
332	}
333	
334	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
335	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
336	// returns the lag-free post-trigger PC (same property as the CSR path).
337	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
338	{
339	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
340	    if (++v->icount_retired < icount_target) return;
341	    on_handoff(vcpu_idx, udata);
342	}
