344	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
345	{
346	    (void) id;
347	    size_t n = qemu_plugin_tb_n_insns(tb);
348	
349	    for (size_t i = 0; i < n; i++) {
350	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
351	
352	        // F14 count tick: registered FIRST so the count is incremented
353	        // before any trigger callback can call exit(200). NO_REGS keeps
354	        // the per-insn cost minimal (a single uint64 add).
355	        if (drain_at_exit_mode) {
356	            qemu_plugin_register_vcpu_insn_exec_cb(
357	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
358	        }
359	
360	        if (icount_mode) {
361	            HandoffSite *site = g_new0(HandoffSite, 1);
362	            site->kind  = HYBRID_HANDOFF_ENTER;
363	            site->vaddr = qemu_plugin_insn_vaddr(insn);
364	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
365	            qemu_plugin_register_vcpu_insn_exec_cb(
366	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
367	        }
368	
369	        if (pc_mode) {
370	            // PC-trigger mode: vaddr-only match. qemu_plugin_insn_size lets
371	            // a future fixture park enter_pc on a compressed insn -- next-PC
372	            // is computed from the API-reported size, not assumed to be 4.
373	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
374	            HandoffSite *site = g_new0(HandoffSite, 1);
375	            site->kind  = HYBRID_HANDOFF_ENTER;
376	            site->vaddr = qemu_plugin_insn_vaddr(insn);
377	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
378	            qemu_plugin_register_vcpu_insn_exec_cb(
379	                insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
380	            continue;
381	        }
382	
383	        // CSR-trigger mode (default).
384	        size_t sz = qemu_plugin_insn_size(insn);
385	        if (sz != 4) continue;
386	        uint32_t raw = 0;
387	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
388	            continue;
389	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
390	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
391	        HandoffSite *site = g_new0(HandoffSite, 1);
392	        site->kind  = kind;
393	        site->vaddr = qemu_plugin_insn_vaddr(insn);
394	        site->size  = (uint32_t) sz;
395	        qemu_plugin_register_vcpu_insn_exec_cb(
396	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
397	    }
398	}
