400	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
401	                                           const qemu_info_t *info,
402	                                           int argc, char **argv)
403	{
404	    (void) info;
405	    for (int i = 0; i < argc; i++) {
406	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
407	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
408	            outfile_path = g_strdup(tok[1]);
409	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
410	            char *endp = NULL;
411	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
412	            if (!endp || *endp != '\0') {
413	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
414	                        tok[1]);
415	                return -1;
416	            }
417	            enter_pc_arg = (uint64_t) v;
418	            pc_mode = 1;
419	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
420	            char *endp = NULL;
421	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
422	            if (!endp || *endp != '\0' || v == 0) {
423	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
424	                        tok[1]);
425	                return -1;
426	            }
427	            icount_target = (uint64_t) v;
428	            icount_mode = 1;
429	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
430	            // F14: any non-zero value enables. "1" is the canonical form
431	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
432	            // also enable -- the flag is a binary switch, not a count.
433	            char *endp = NULL;
434	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
435	            if (!endp || *endp != '\0') {
436	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
437	                        tok[1]);
438	                return -1;
439	            }
440	            drain_at_exit_mode = (v != 0);
441	        } else {
442	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
443	            return -1;
444	        }
445	    }
446	    if (!outfile_path) {
447	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
448	        return -1;
449	    }
450	    if (pc_mode) {
451	        fprintf(stderr,
452	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
453	                enter_pc_arg);
454	    }
455	    if (icount_mode) {
456	        fprintf(stderr,
457	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
458	                icount_target);
459	    }
460	    if (drain_at_exit_mode) {
461	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
462	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
463	    }
464	
465	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
466	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
467	    return 0;
468	}
